import { useEffect, useMemo, useRef, useState } from "react";
import { io, Socket } from "socket.io-client";

type User = { id:string; username:string; displayName:string; bio:string; avatarUrl:string|null; age:number|null; agePublic:boolean; role?:string; statusEmoji?:string|null; online?:boolean; lastSeenAt?:string|null; theme?:"dark"|"light" };
type Chat = { chatId:string; type:"direct"|"group"; title:string|null; user:User|null; members:User[]; lastMessage:string|null };
type Message = { id:string; chatId:string; senderId:string; body:string; createdAt:string; messageType?:"text"|"image"|"audio"; mediaUrl?:string|null; username?:string; displayName?:string };
type Page = "chat"|"updates"|"settings"|"notes"|"support"|"admin";
type CallSession = {chatId:string;peerId:string;peerName:string;peerAvatar:string|null;video:boolean;status:"incoming"|"calling"|"connecting"|"active";offer?:RTCSessionDescriptionInit};
const api = async (path:string, token:string|null, options:RequestInit={}) => {
  const headers = new Headers(options.headers);
  if (token) headers.set("Authorization", "Bearer " + token);
  if (options.body && !(options.body instanceof FormData)) headers.set("Content-Type","application/json");
  const response = await fetch("/api" + path, { ...options, headers });
  const data = await response.json().catch(()=>({}));
  if (!response.ok) throw new Error(data.error || "Ошибка запроса");
  return data;
};
const emptyUser:User = {id:"",username:"",displayName:"",bio:"",avatarUrl:null,age:null,agePublic:false};
const emojiList=["😀","😂","🥹","😍","😎","😭","🤔","😴","🔥","❤️","💜","👍","👎","👏","🙏","🎉","💯","🤣","😘","🥰","😡","🤝","✨","💀","🚀","👀","🥳","😅","🙃","💔","🤍","🫶"];

export default function App() {
  const [token,setToken] = useState(localStorage.getItem("dtr_token"));
  const [me,setMe] = useState<User|null>(null);
  const [mode,setMode] = useState<"login"|"register">("login");
  const [username,setUsername] = useState("");
  const [password,setPassword] = useState("");
  const [displayName,setDisplayName] = useState("");
  const [error,setError] = useState("");
  const [busy,setBusy] = useState(false);
  const [entered,setEntered] = useState(false);
  const [page,setPage] = useState<Page>("chat");
  const [chats,setChats] = useState<Chat[]>([]);
  const [active,setActive] = useState<Chat|null>(null);
  const [messages,setMessages] = useState<Message[]>([]);
  const [search,setSearch] = useState("");
  const [results,setResults] = useState<User[]>([]);
  const [draft,setDraft] = useState("");
  const [emojiOpen,setEmojiOpen] = useState(false);
  const [profileTarget,setProfileTarget] = useState<User|null>(null);
  const [editOpen,setEditOpen] = useState(false);
  const [editName,setEditName] = useState("");
  const [editBio,setEditBio] = useState("");
  const [editAge,setEditAge] = useState("");
  const [editAgePublic,setEditAgePublic] = useState(false);
  const [groupOpen,setGroupOpen] = useState(false);
  const [groupTitle,setGroupTitle] = useState("");
  const [groupSearch,setGroupSearch] = useState("");
  const [groupResults,setGroupResults] = useState<User[]>([]);
  const [selectedUsers,setSelectedUsers] = useState<User[]>([]);
  const [groupInfoOpen,setGroupInfoOpen] = useState(false);
  const [groupAddSearch,setGroupAddSearch] = useState("");
  const [groupAddResults,setGroupAddResults] = useState<User[]>([]);
  const [recording,setRecording] = useState(false);
  const [uploadingMedia,setUploadingMedia] = useState(false);
  const [compact,setCompact] = useState(localStorage.getItem("dtr_compact")==="true");
  const [theme,setTheme] = useState<"dark"|"light">(localStorage.getItem("dtr_theme")==="light"?"light":"dark");
  const [notes,setNotes] = useState<any[]>([]);
  const [noteTitle,setNoteTitle] = useState("");
  const [noteBody,setNoteBody] = useState("");
  const [tickets,setTickets] = useState<any[]>([]);
  const [selectedTicket,setSelectedTicket] = useState<any|null>(null);
  const [supportMessages,setSupportMessages] = useState<any[]>([]);
  const [supportSubject,setSupportSubject] = useState("");
  const [supportBody,setSupportBody] = useState("");
  const [supportCategory,setSupportCategory] = useState("question");
  const [supportDraft,setSupportDraft] = useState("");
  const [adminSearch,setAdminSearch] = useState("");
  const [adminResults,setAdminResults] = useState<User[]>([]);
  const [notificationsEnabled,setNotificationsEnabled] = useState(false);
  const [notificationBusy,setNotificationBusy] = useState(false);
  const [call,setCall] = useState<CallSession|null>(null);
  const [localStream,setLocalStream] = useState<MediaStream|null>(null);
  const [remoteStream,setRemoteStream] = useState<MediaStream|null>(null);
  const [micMuted,setMicMuted] = useState(false);
  const [cameraOff,setCameraOff] = useState(false);
  const [speakerOn,setSpeakerOn] = useState(false);
  const pcRef = useRef<RTCPeerConnection|null>(null);
  const localStreamRef = useRef<MediaStream|null>(null);
  const pendingIceRef = useRef<RTCIceCandidateInit[]>([]);
  const remoteVideoRef = useRef<HTMLVideoElement>(null);
  const localVideoRef = useRef<HTMLVideoElement>(null);
  const photoInput = useRef<HTMLInputElement>(null);
  const recorder = useRef<MediaRecorder|null>(null);
  const recorderChunks = useRef<Blob[]>([]);
  const recorderTimer = useRef<number|null>(null);
  const socket = useMemo<Socket|null>(()=> token ? io({auth:{token}}) : null,[token]);

  // Keep the underlying messenger viewport fixed while a modal is open.
  // Telegram's Android WebView can otherwise scroll the page when a modal closes.
  useEffect(()=>{
    const modalOpen=Boolean(profileTarget||editOpen||groupOpen||groupInfoOpen);
    if(!modalOpen)return;
    const y=window.scrollY||document.documentElement.scrollTop||0;
    const body=document.body;
    const previous={position:body.style.position,top:body.style.top,left:body.style.left,right:body.style.right,width:body.style.width,overflow:body.style.overflow};
    body.style.position="fixed";
    body.style.top=`-${y}px`;
    body.style.left="0";
    body.style.right="0";
    body.style.width="100%";
    body.style.overflow="hidden";
    return ()=>{
      body.style.position=previous.position;
      body.style.top=previous.top;
      body.style.left=previous.left;
      body.style.right=previous.right;
      body.style.width=previous.width;
      body.style.overflow=previous.overflow;
      window.scrollTo(0,y);
    };
  },[profileTarget,editOpen,groupOpen,groupInfoOpen]);

  async function refreshChats(){ if(!token)return; try{const d=await api("/chats",token);setChats(d.chats||[]);}catch(e:any){setError(e.message)} }
  useEffect(()=>{ if(!token)return; api("/me",token).then(d=>{setMe(d.user);setTheme(d.user.theme==="light"?"light":"dark");localStorage.setItem("dtr_theme",d.user.theme==="light"?"light":"dark");setEditName(d.user.displayName);setEditBio(d.user.bio||"");setEditAge(d.user.age===null?"":String(d.user.age));setEditAgePublic(Boolean(d.user.agePublic));}).catch(()=>logout()); refreshChats(); return ()=>{socket?.disconnect()}; },[token,socket]);
  useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem("dtr_theme",theme);},[theme]);
  useEffect(()=>{if(!socket)return;const presence=(d:any)=>{const update=(u:User|null)=>u&&u.id===String(d.userId)?{...u,online:Boolean(d.online),lastSeenAt:d.lastSeenAt||null}:u;setMe(old=>update(old));setProfileTarget(old=>update(old));setChats(old=>old.map(c=>({...c,user:update(c.user),members:c.members.map(m=>update(m) as User)})));};const role=()=>{if(me)api("/me",token).then(d=>setMe(d.user)).catch(()=>{});};socket.on("presence:update",presence);socket.on("user:role-updated",role);socket.on("support:refresh",()=>{if(page==="support")loadTickets();});const supportMessage=(d:any)=>{if(selectedTicket&&String(selectedTicket.id)===String(d.ticketId))setSupportMessages(old=>old.some(m=>String(m.id)===String(d.message.id))?old:[...old,d.message]);};socket.on("support:message",supportMessage);return()=>{socket.off("presence:update",presence);socket.off("user:role-updated",role);socket.off("support:refresh");socket.off("support:message",supportMessage);};},[socket,me,token,page,selectedTicket]);
  useEffect(()=>{ if(!socket)return; const receive=(m:Message)=>{if(active?.chatId===m.chatId)setMessages(old=>old.some(x=>x.id===m.id)?old:[...old,m]);refreshChats();}; const refresh=()=>refreshChats(); socket.on("chat:message",receive);socket.on("chat:refresh",refresh);return ()=>{socket.off("chat:message",receive);socket.off("chat:refresh",refresh)};},[socket,active,token]);
  useEffect(()=>{if(!token||!("serviceWorker" in navigator)||!("PushManager" in window))return;let live=true;navigator.serviceWorker.register("/sw.js").then(reg=>reg.pushManager.getSubscription()).then(sub=>{if(live)setNotificationsEnabled(Boolean(sub))}).catch(()=>{});return()=>{live=false};},[token]);
  useEffect(()=>{if(!call)return;if(call.video&&remoteVideoRef.current&&remoteStream)remoteVideoRef.current.srcObject=remoteStream;if(!call.video&&remoteAudioRef.current&&remoteStream)remoteAudioRef.current.srcObject=remoteStream;if(localVideoRef.current&&localStream)localVideoRef.current.srcObject=localStream;},[call,remoteStream,localStream]);
  useEffect(()=>{if(!socket)return;const incoming=async(data:any)=>{if(call){socket.emit("call:end",{to:data.from,chatId:data.chatId});return;}try{const d=await api("/users/"+data.from+"/profile",token);setCall({chatId:data.chatId,peerId:String(data.from),peerName:d.user.displayName,peerAvatar:d.user.avatarUrl,video:Boolean(data.video),status:"incoming",offer:data.offer});}catch{socket.emit("call:end",{to:data.from,chatId:data.chatId});}};const answered=async(data:any)=>{if(!pcRef.current||!call)return;try{await pcRef.current.setRemoteDescription(new RTCSessionDescription(data.answer));for(const candidate of pendingIceRef.current.splice(0))await pcRef.current.addIceCandidate(new RTCIceCandidate(candidate));setCall(old=>old?{...old,status:"connecting"}:old);}catch{setError("Не удалось подключить звонок.");}};const ice=async(data:any)=>{if(call&&data.chatId!==call.chatId)return;try{if(pcRef.current?.remoteDescription)await pcRef.current.addIceCandidate(new RTCIceCandidate(data.candidate));else pendingIceRef.current.push(data.candidate);}catch{}};const ended=()=>finishCall(false);socket.on("call:incoming",incoming);socket.on("call:answered",answered);socket.on("call:ice-candidate",ice);socket.on("call:ended",ended);return()=>{socket.off("call:incoming",incoming);socket.off("call:answered",answered);socket.off("call:ice-candidate",ice);socket.off("call:ended",ended)};},[socket,token,call]);
  useEffect(()=>{if(!token||search.trim().length<2){setResults([]);return;}const t=window.setTimeout(()=>api("/users/search?q="+encodeURIComponent(search),token).then(d=>setResults(d.users)).catch(e=>setError(e.message)),250);return()=>window.clearTimeout(t);},[search,token]);
  useEffect(()=>{if(!groupOpen||!token||groupSearch.trim().length<2){setGroupResults([]);return;}const t=window.setTimeout(()=>api("/users/search?q="+encodeURIComponent(groupSearch),token).then(d=>setGroupResults(d.users.filter((u:User)=>!selectedUsers.some(x=>x.id===u.id)))).catch(e=>setError(e.message)),250);return()=>window.clearTimeout(t);},[groupSearch,groupOpen,token,selectedUsers]);
  useEffect(()=>{if(!groupInfoOpen||!token||groupAddSearch.trim().length<2){setGroupAddResults([]);return;}const t=window.setTimeout(()=>api("/users/search?q="+encodeURIComponent(groupAddSearch),token).then(d=>setGroupAddResults(d.users.filter((u:User)=>!active?.members?.some(x=>x.id===u.id)))).catch(e=>setError(e.message)),250);return()=>window.clearTimeout(t);},[groupAddSearch,groupInfoOpen,token,active]);
  function logout(){localStorage.removeItem("dtr_token");setToken(null);setMe(null);setEntered(false);setChats([]);setActive(null);setMessages([]);setPage("chat");socket?.disconnect();}
  async function submitAuth(e:React.FormEvent){e.preventDefault();setError("");setBusy(true);try{const d=await api("/auth/"+mode,null,{method:"POST",body:JSON.stringify({username,password,displayName})});localStorage.setItem("dtr_token",d.token);setToken(d.token);setMe(d.user);setEntered(false);}catch(e:any){setError(e.message)}finally{setBusy(false)}}
  async function openChat(user:User){setPage("chat");setGroupOpen(false);try{const d=await api("/chats/open",token,{method:"POST",body:JSON.stringify({userId:user.id})});const c=await api("/chats",token);setChats(c.chats);const chat=c.chats.find((x:Chat)=>x.chatId===d.chatId);if(chat)await selectChat(chat);else{const fallback:Chat={chatId:d.chatId,type:"direct",title:null,user,members:[me||emptyUser,user],lastMessage:null};await selectChat(fallback);}setSearch("");setResults([]);}catch(e:any){setError(e.message)}}
  async function selectChat(chat:Chat){setPage("chat");setActive(chat);setProfileTarget(null);setGroupInfoOpen(false);try{const d=await api("/chats/"+chat.chatId+"/messages",token);setMessages(d.messages||[]);}catch(e:any){setError(e.message)}}
  async function send(e:React.FormEvent){e.preventDefault();if(!draft.trim()||!active)return;const body=draft.trim();setDraft("");try{const d=await api("/chats/"+active.chatId+"/messages",token,{method:"POST",body:JSON.stringify({body})});setMessages(old=>old.some(x=>x.id===d.message.id)?old:[...old,d.message]);refreshChats();}catch(e:any){setError(e.message);setDraft(body)}}
  async function sendMedia(file?:File){if(!file||!active)return;if(file.size>12*1024*1024){setError("Файл слишком большой. Максимум 12 МБ.");return;}const form=new FormData();form.append("media",file);const controller=new AbortController();const timeout=window.setTimeout(()=>controller.abort(),45000);setUploadingMedia(true);try{const d=await api("/chats/"+active.chatId+"/media",token,{method:"POST",body:form,signal:controller.signal});setMessages(old=>old.some(x=>x.id===d.message.id)?old:[...old,d.message]);refreshChats();}catch(e:any){setError(e.name==="AbortError"?"Загрузка заняла слишком много времени. Попробуй фото меньшего размера.":e.message)}finally{window.clearTimeout(timeout);setUploadingMedia(false);if(photoInput.current)photoInput.current.value="";}}
  async function startRecording(){if(!active||recording)return;if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==="undefined"){setError("Запись голоса не поддерживается этим браузером.");return;}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const types=["audio/webm;codecs=opus","audio/webm","audio/mp4","audio/ogg;codecs=opus"];const mimeType=types.find(type=>MediaRecorder.isTypeSupported(type));const mediaRecorder=mimeType?new MediaRecorder(stream,{mimeType}):new MediaRecorder(stream);recorderChunks.current=[];mediaRecorder.ondataavailable=(event)=>{if(event.data.size)recorderChunks.current.push(event.data)};mediaRecorder.onerror=()=>setError("Не удалось записать голосовое сообщение.");mediaRecorder.onstop=async()=>{const blob=new Blob(recorderChunks.current,{type:mediaRecorder.mimeType||"audio/webm"});stream.getTracks().forEach(track=>track.stop());recorder.current=null;if(blob.size){const ext=blob.type.includes("mp4")?"m4a":blob.type.includes("ogg")?"ogg":"webm";await sendMedia(new File([blob],"voice-"+Date.now()+"."+ext,{type:blob.type||"audio/webm"}));}};recorder.current=mediaRecorder;mediaRecorder.start(250);setRecording(true);recorderTimer.current=window.setTimeout(()=>{if(recorder.current?.state==="recording")recorder.current.stop();setRecording(false);setError("Голосовое сообщение остановлено через 90 секунд.");},90000);}catch(e:any){setError(e.name==="NotAllowedError"?"Разреши доступ к микрофону в настройках браузера.":"Не удалось включить микрофон.");}}
  function stopRecording(){if(recorderTimer.current!==null){window.clearTimeout(recorderTimer.current);recorderTimer.current=null;}if(recorder.current?.state==="recording")recorder.current.stop();setRecording(false);}
  function openEditProfile(){if(!me)return;setEditName(me.displayName);setEditBio(me.bio||"");setEditAge(me.age===null?"":String(me.age));setEditAgePublic(Boolean(me.agePublic));setEditOpen(true);}
  async function saveProfile(){try{const d=await api("/profile",token,{method:"PATCH",body:JSON.stringify({displayName:editName,bio:editBio,age:editAge===""?null:Number(editAge),agePublic:editAgePublic})});setMe(d.user);setEditOpen(false);if(profileTarget?.id===d.user.id)setProfileTarget(d.user);refreshChats();}catch(e:any){setError(e.message)}}
  async function uploadAvatar(file?:File){if(!file)return;const data=new FormData();data.append("avatar",file);try{const d=await api("/profile/avatar",token,{method:"POST",body:data});setMe(d.user);if(profileTarget?.id===d.user.id)setProfileTarget(d.user);}catch(e:any){setError(e.message)}}
  async function viewProfile(user:User|null){if(!user)return;try{const d=await api("/users/"+user.id+"/profile",token);setProfileTarget(d.user);}catch(e:any){setError(e.message)}}
  async function createGroup(){if(!groupTitle.trim()||selectedUsers.length===0)return;setBusy(true);try{const d=await api("/chats/group",token,{method:"POST",body:JSON.stringify({title:groupTitle.trim(),userIds:selectedUsers.map(u=>u.id)})});const c=await api("/chats",token);setChats(c.chats);const chat=c.chats.find((x:Chat)=>x.chatId===d.chatId);if(chat)await selectChat(chat);setGroupOpen(false);setGroupTitle("");setGroupSearch("");setSelectedUsers([]);}catch(e:any){setError(e.message)}finally{setBusy(false)}}
  async function addGroupMember(user:User){if(!active)return;try{await api("/chats/"+active.chatId+"/members",token,{method:"POST",body:JSON.stringify({userId:user.id})});await refreshChats();const c=await api("/chats",token);const updated=c.chats.find((x:Chat)=>x.chatId===active.chatId);if(updated)setActive(updated);setGroupAddSearch("");setGroupAddResults([]);}catch(e:any){setError(e.message)}}

  async function changeTheme(next:"dark"|"light"){setTheme(next);try{const d=await api("/profile/preferences",token,{method:"PATCH",body:JSON.stringify({theme:next})});setMe(d.user);}catch(e:any){setError(e.message);}}
  async function setStatusEmoji(statusEmoji:string|null){try{const d=await api("/profile/status",token,{method:"PATCH",body:JSON.stringify({statusEmoji})});setMe(d.user);}catch(e:any){setError(e.message);}}
  async function loadNotes(){try{const d=await api("/notes",token);setNotes(d.notes||[]);}catch(e:any){setError(e.message);}}
  async function saveNote(){if(!noteTitle.trim()&&!noteBody.trim())return;try{await api("/notes",token,{method:"POST",body:JSON.stringify({title:noteTitle,body:noteBody})});setNoteTitle("");setNoteBody("");await loadNotes();}catch(e:any){setError(e.message);}}
  async function deleteNote(id:string){try{await api("/notes/"+id,token,{method:"DELETE"});setNotes(old=>old.filter(n=>n.id!==id));}catch(e:any){setError(e.message);}}
  async function loadTickets(){try{const d=await api("/support/tickets",token);setTickets(d.tickets||[]);}catch(e:any){setError(e.message);}}
  async function openTicket(ticket:any){setSelectedTicket(ticket);try{const d=await api("/support/tickets/"+ticket.id+"/messages",token);setSupportMessages(d.messages||[]);}catch(e:any){setError(e.message);}}
  async function createTicket(){if(!supportSubject.trim()||!supportBody.trim())return;try{const d=await api("/support/tickets",token,{method:"POST",body:JSON.stringify({subject:supportSubject,body:supportBody,category:supportCategory})});setSupportSubject("");setSupportBody("");await loadTickets();await openTicket(d.ticket);}catch(e:any){setError(e.message);}}
  async function sendSupportReply(){if(!selectedTicket||!supportDraft.trim())return;const body=supportDraft.trim();setSupportDraft("");try{await api("/support/tickets/"+selectedTicket.id+"/messages",token,{method:"POST",body:JSON.stringify({body})});await openTicket(selectedTicket);await loadTickets();}catch(e:any){setSupportDraft(body);setError(e.message);}}
  async function updateTicketStatus(status:string){if(!selectedTicket)return;try{await api("/support/tickets/"+selectedTicket.id+"/status",token,{method:"PATCH",body:JSON.stringify({status})});setSelectedTicket({...selectedTicket,status});await loadTickets();}catch(e:any){setError(e.message);}}
  async function assignRole(user:User,role:string){try{await api("/admin/users/"+user.id+"/role",token,{method:"PATCH",body:JSON.stringify({role})});setAdminResults(old=>old.map(u=>u.id===user.id?{...u,role}:u));if(profileTarget?.id===user.id)setProfileTarget({...profileTarget,role});}catch(e:any){setError(e.message);}}

  function toggleCompact(){const next=!compact;setCompact(next);localStorage.setItem("dtr_compact",String(next));}
  function finishCall(notifyPeer=true){audioSourceRef.current?.disconnect();audioSourceRef.current=null;void audioContextRef.current?.close();audioContextRef.current=null;if(remoteAudioRef.current)remoteAudioRef.current.muted=false;if(remoteVideoRef.current)remoteVideoRef.current.muted=false;if(notifyPeer&&call&&socket)socket.emit("call:end",{to:call.peerId,chatId:call.chatId});pcRef.current?.close();pcRef.current=null;localStreamRef.current?.getTracks().forEach(track=>track.stop());localStreamRef.current=null;pendingIceRef.current=[];setLocalStream(null);setRemoteStream(null);setCall(null);setMicMuted(false);setCameraOff(false);setSpeakerOn(false);}
  function makePeer(peerId:string,chatId:string){const pc=new RTCPeerConnection({iceServers:[{urls:"stun:stun.l.google.com:19302"}]});pcRef.current=pc;pc.onicecandidate=e=>{if(e.candidate)socket?.emit("call:ice",{to:peerId,chatId,candidate:e.candidate.toJSON()});};pc.ontrack=e=>{if(e.streams[0])setRemoteStream(e.streams[0]);};pc.onconnectionstatechange=()=>{if(pc.connectionState==="connected")setCall(old=>old?{...old,status:"active"}:old);if(pc.connectionState==="failed")setError("Не удалось соединить устройства. Попробуй ещё раз.");};return pc;}
  async function startCall(video:boolean){if(!active||active.type!=="direct"||!active.user||call)return;try{const stream=await navigator.mediaDevices.getUserMedia({audio:true,video});localStreamRef.current=stream;setLocalStream(stream);setCall({chatId:active.chatId,peerId:active.user.id,peerName:active.user.displayName,peerAvatar:active.user.avatarUrl,video,status:"calling"});const pc=makePeer(active.user.id,active.chatId);stream.getTracks().forEach(track=>pc.addTrack(track,stream));const offer=await pc.createOffer();await pc.setLocalDescription(offer);socket?.emit("call:offer",{to:active.user.id,chatId:active.chatId,offer,video});}catch(e:any){finishCall(false);setError(e.name==="NotAllowedError"?"Разреши доступ к микрофону и камере в браузере.":"Не удалось начать звонок.");}}
  async function acceptCall(){if(!call?.offer)return;try{const stream=await navigator.mediaDevices.getUserMedia({audio:true,video:call.video});localStreamRef.current=stream;setLocalStream(stream);const pc=makePeer(call.peerId,call.chatId);await pc.setRemoteDescription(new RTCSessionDescription(call.offer));stream.getTracks().forEach(track=>pc.addTrack(track,stream));for(const candidate of pendingIceRef.current.splice(0))await pc.addIceCandidate(new RTCIceCandidate(candidate));const answer=await pc.createAnswer();await pc.setLocalDescription(answer);socket?.emit("call:answer",{to:call.peerId,chatId:call.chatId,answer});setCall(old=>old?{...old,status:"connecting",offer:undefined}:old);}catch(e:any){finishCall();setError(e.name==="NotAllowedError"?"Разреши доступ к микрофону и камере.":"Не удалось принять звонок.");}}
  async function toggleSpeaker(){const element=(call?.video?remoteVideoRef.current:remoteAudioRef.current) as (HTMLMediaElement & {setSinkId?:(id:string)=>Promise<void>})|null;if(!element){setError("Звук ещё не подключился.");return;}try{const next=!speakerOn;if(element.setSinkId){if(next){const md=navigator.mediaDevices as MediaDevices & {selectAudioOutput?:()=>Promise<MediaDeviceInfo>};let device:MediaDeviceInfo|undefined; if(md.selectAudioOutput)device=await md.selectAudioOutput();else{const outputs=(await navigator.mediaDevices.enumerateDevices()).filter(d=>d.kind==="audiooutput");device=outputs.find(d=>/speaker|loudspeaker|громк|динамик/i.test(d.label))||outputs.find(d=>d.deviceId!=="default");}if(!device){setError("Браузер не открыл выбор динамика. Переключи звук через системную панель Android.");return;}await element.setSinkId(device.deviceId);}else await element.setSinkId("default");setSpeakerOn(next);return;}const Ctx=window.AudioContext;const proto=Ctx?.prototype as any;if(proto&&typeof proto.setSinkId==="function"&&remoteStream){if(next){const ctx=new Ctx();const source=ctx.createMediaStreamSource(remoteStream);source.connect(ctx.destination);const outputs=(await navigator.mediaDevices.enumerateDevices()).filter(d=>d.kind==="audiooutput");const speaker=outputs.find(d=>/speaker|loudspeaker|громк|динамик/i.test(d.label))||outputs.find(d=>d.deviceId!=="default");if(!speaker){await ctx.close();setError("Браузер не показал доступный динамик. Используй системную панель Android.");return;}await (ctx as any).setSinkId(speaker.deviceId);audioContextRef.current=ctx;audioSourceRef.current=source;if(remoteAudioRef.current)remoteAudioRef.current.muted=true;if(remoteVideoRef.current)remoteVideoRef.current.muted=true;}else{audioSourceRef.current?.disconnect();audioSourceRef.current=null;await audioContextRef.current?.close();audioContextRef.current=null;if(remoteAudioRef.current)remoteAudioRef.current.muted=false;if(remoteVideoRef.current)remoteVideoRef.current.muted=false;}setSpeakerOn(next);return;}setError("В этой версии Яндекс Браузера нет API для принудительного выбора динамика. Во время звонка переключи вывод звука через системную панель Android.");}catch(e:any){setError(e?.name==="NotAllowedError"?"Браузер запретил выбор аудиовыхода. Разреши доступ к микрофону и устройствам звука.":"Не удалось сменить аудиовыход. Используй системную панель Android.");}}
  async function enableNotifications(){setNotificationBusy(true);try{if(!window.isSecureContext||!("serviceWorker" in navigator)||!("PushManager" in window)||!("Notification" in window))throw new Error("Этот браузер или режим открытия не поддерживает Web Push. Открой DTR как сайт по HTTPS и проверь поддержку уведомлений.");let permission=Notification.permission;if(permission!=="granted")permission=await Notification.requestPermission();if(permission!=="granted")throw new Error("Разрешение на уведомления не выдано.");const d=await api("/push/public-key",token);const reg=await navigator.serviceWorker.register("/sw.js");const sub=await reg.pushManager.getSubscription()||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:base64ToBytes(d.publicKey)});await api("/push/subscribe",token,{method:"POST",body:JSON.stringify(sub)});setNotificationsEnabled(true);}catch(e:any){setError(e.message||"Не удалось включить уведомления.");}finally{setNotificationBusy(false);}}
  async function disableNotifications(){setNotificationBusy(true);try{const reg=await navigator.serviceWorker.getRegistration("/");const sub=await reg?.pushManager.getSubscription();if(sub){await api("/push/subscribe",token,{method:"DELETE",body:JSON.stringify({endpoint:sub.endpoint})});await sub.unsubscribe();}setNotificationsEnabled(false);}catch(e:any){setError(e.message)}finally{setNotificationBusy(false);}}
  function base64ToBytes(value:string){const pad="=".repeat((4-value.length%4)%4);const raw=window.atob((value+pad).replace(/-/g,"+").replace(/_/g,"/"));return Uint8Array.from([...raw].map(c=>c.charCodeAt(0))).buffer as ArrayBuffer;}
  async function changeAgeVisibility(next:boolean){setEditAgePublic(next);if(!me)return;try{const d=await api("/profile",token,{method:"PATCH",body:JSON.stringify({displayName:me.displayName,bio:me.bio,age:me.age,agePublic:next})});setMe(d.user);}catch(e:any){setError(e.message);setEditAgePublic(Boolean(me.agePublic));}}

  useEffect(()=>{if(page!=="admin"||adminSearch.trim().length<2){setAdminResults([]);return;}const t=window.setTimeout(()=>api("/users/search?q="+encodeURIComponent(adminSearch),token).then(d=>setAdminResults(d.users||[])).catch(e=>setError(e.message)),250);return()=>window.clearTimeout(t);},[adminSearch,page,token]);
  if(!token||!me)return <main className="auth"><form className="auth-card" onSubmit={submitAuth}><div className="auth-kicker">ПРОСТО. ЛИЧНО. DTR.</div><div className="brand-mark">д</div><h1>дтр</h1><p>Твои разговоры. В одном месте.</p><div className="auth-features"><span>Личные и групповые чаты</span><span>Фото и голосовые</span><span>Профили и настройки</span></div>{mode==="register"&&<input placeholder="Отображаемое имя" value={displayName} onChange={e=>setDisplayName(e.target.value)} maxLength={40}/>}<input placeholder="Логин" value={username} onChange={e=>setUsername(e.target.value)} minLength={3} maxLength={24} required/><input placeholder="Пароль (минимум 8 символов)" type="password" value={password} onChange={e=>setPassword(e.target.value)} minLength={8} required/><button disabled={busy}>{busy?"Подождите…":mode==="login"?"Войти":"Создать аккаунт"}</button><button type="button" className="link" onClick={()=>setMode(mode==="login"?"register":"login")}>{mode==="login"?"Нет аккаунта? Регистрация":"Уже есть аккаунт? Войти"}</button>{error&&<div className="error">{error}</div>}</form></main>;
  if(!entered)return <main className="welcome-screen"><div className="welcome-orb orb-one"></div><div className="welcome-orb orb-two"></div><section className="welcome-card"><div className="welcome-brand"><div className="brand-mark">д</div><span>DTR <i>MESSENGER</i></span></div><div className="welcome-avatar"><Avatar user={me}/></div><div className="welcome-kicker">РАДЫ СНОВА ТЕБЯ ВИДЕТЬ</div><h1>Привет, {me.displayName}.</h1><p className="welcome-copy">Твоё пространство для общения уже готово. Продолжай разговоры или найди кого-нибудь по логину.</p><div className="welcome-highlights"><div><b>01</b><span>Личные<br/>переписки</span></div><div><b>02</b><span>Групповые<br/>чаты</span></div><div><b>03</b><span>Профили<br/>и настройки</span></div></div><button className="welcome-enter" onClick={()=>setEntered(true)}>Открыть DTR <span>→</span></button><button className="welcome-logout" onClick={logout}>Выйти из аккаунта</button><small className="welcome-version">DTR MESSENGER · VERSION 0.6.0</small></section></main>;

  const activeTitle=active?.type==="group"?(active.title||"Групповой чат"):(active?.user?.displayName||"Чат");
  const activeSubtitle=active?.type==="group"?(String(active.members?.length||0)+" участников"):(active?.user?presenceText(active.user):"");
  return <main className={"shell"+(compact?" compact-mode":"")+(theme==="light"?" theme-light":"")}>
    <aside className={"sidebar"+(active?" mobile-hidden":"")}>
      <header className="side-head"><div className="brand-mark small">д</div><strong>дтр</strong><button className="icon-btn" onClick={()=>setPage("settings")} title="Настройки">⚙</button></header>
      <button className="my-profile" onClick={()=>viewProfile(me)}><Avatar user={me}/><span><b>{me.displayName}</b><small>@{me.username}</small></span><span className="profile-arrow">›</span></button>
      <div className="section-title">СООБЩЕНИЯ</div>
      <div className="search-row"><input className="search" placeholder="Найти по логину…" value={search} onChange={e=>setSearch(e.target.value)}/><button className="new-group-btn" onClick={()=>setGroupOpen(true)} title="Создать группу">＋</button></div>
      {search&&results.map(u=><button className="person" key={u.id} onClick={()=>openChat(u)}><Avatar user={u}/><span><b>{u.displayName}</b><small>@{u.username}</small></span></button>)}
      {search&&results.length===0&&search.length>=2&&<p className="muted">Никого не найдено</p>}
      <div className="chat-list">{chats.map(c=><button className={active?.chatId===c.chatId?"chat active":"chat"} key={c.chatId} onClick={()=>selectChat(c)}><Avatar user={c.type==="group"?null:c.user} label={c.type==="group"?(c.title||"Г").slice(0,1):undefined}/><span><b>{c.type==="group"?(c.title||"Группа"):(c.user?.displayName||"Пользователь")}</b><small>{c.lastMessage|| (c.type==="group"?"Групповой чат":"Начните общение")}</small></span><small className="chat-kind">{c.type==="group"?"ГРУППА":""}</small></button>)}</div>
      <footer><button className="updates-link" onClick={()=>{setPage("updates");setActive(null)}}>Обновления · v0.6.0</button><button className="updates-link" onClick={()=>{setPage("notes");setActive(null);loadNotes();}}>Заметки</button><button className="updates-link" onClick={()=>{setPage("support");setActive(null);setSelectedTicket(null);loadTickets();}}>Поддержка</button>{["owner","admin"].includes(me.role||"")&&<button className="updates-link" onClick={()=>{setPage("admin");setActive(null);}}>Панель управления</button>}<button className="updates-link" onClick={()=>{setPage("settings");setActive(null)}}>Настройки</button></footer>
    </aside>
    <section className={"conversation"+(active?" mobile-conversation":"")}>
      {page==="updates"?<><header className="conversation-head"><button className="back-btn" onClick={()=>setPage("chat")}>←</button><div><b>Обновления DTR</b><small>Версия 0.6.0</small></div></header><div className="messages updates-content"><article className="release-card current-release"><span className="release-version">v0.6.0 · НОВОЕ</span><h2>Личное пространство и команда DTR</h2><ul><li>Роли пользователей и панель управления.</li><li>Центр поддержки с очередью обращений для команды.</li><li>Личные заметки, светлая и тёмная темы.</li><li>Статус активности, время последнего посещения и эмодзи у аватара.</li><li>Расширенные настройки приватности и правила сервиса.</li></ul></article><article className="release-card"><span className="release-version">v0.5.0</span><h2>Голосовые и видеозвонки</h2><p>Входящие звонки, управление микрофоном и камерой, push-уведомления и установка DTR как приложения.</p></article><article className="release-card"><span className="release-version">v0.4.0</span><h2>Группы и профили</h2><p>Групповые чаты, профили собеседников, настройки и мобильная навигация.</p></article><article className="release-card"><span className="release-version">v0.3.0</span><h2>Фото и голосовые</h2><p>Изображения до 12 МБ, голосовые до 90 секунд и защищённая выдача вложений.</p></article></div></>
:page==="settings"?<><header className="conversation-head"><button className="back-btn" onClick={()=>setPage("chat")}>←</button><div><b>Настройки</b><small>Персонализация и безопасность</small></div></header><div className="messages settings-content">
<section className="settings-card"><div className="settings-profile"><Avatar user={me}/><div><b>{me.displayName}</b><small>@{me.username} · {roleLabel(me.role)}</small></div></div><button className="primary-action" onClick={openEditProfile}>Изменить профиль <span>›</span></button><button className="settings-row" onClick={()=>viewProfile(me)}>Посмотреть мой профиль <span>›</span></button></section>
<section className="settings-card"><h3>Оформление</h3><div className="theme-choice"><button className={theme==="dark"?"theme-option selected":"theme-option"} onClick={()=>changeTheme("dark")}>🌙 Тёмная</button><button className={theme==="light"?"theme-option selected":"theme-option"} onClick={()=>changeTheme("light")}>☀️ Светлая</button></div><label className="setting-toggle"><span><b>Компактный список чатов</b><small>Больше переписок на экране</small></span><input type="checkbox" checked={compact} onChange={toggleCompact}/></label><div className="status-emoji-row"><span><b>Эмодзи рядом с аватаром</b><small>Как значок статуса в Telegram</small></span><div>{["","💜","🔥","⭐","🎮","🎧","💬","🌙","🫶","👑","✨"].map(e=><button key={e||"none"} className="status-emoji-choice" onClick={()=>setStatusEmoji(e||null)}>{e||"×"}</button>)}</div></div></section>
<section className="settings-card"><h3>Уведомления</h3><div className="settings-row static-row">{notificationsEnabled?"Push-уведомления включены":"Уведомления не подключены"}</div><button className="primary-action" onClick={notificationsEnabled?disableNotifications:enableNotifications} disabled={notificationBusy}>{notificationBusy?"Подождите…":notificationsEnabled?"Отключить push":"Включить push-уведомления"} <span>›</span></button><p className="settings-hint">Для доставки при закрытом сайте нужны разрешение браузера, HTTPS и поддержка Web Push. Встроенное окно Telegram и некоторые сборки мобильных браузеров могут ограничивать push. DTR не может обойти системные ограничения Android.</p><div className="settings-row static-row">Звук звонка <small>Маршрутизацию на динамик выбирает Android, если браузер не предоставляет выбор аудиовыхода.</small></div></section>
<section className="settings-card"><h3>Приватность и безопасность</h3><label className="setting-toggle"><span><b>Показывать возраст в профиле</b><small>По умолчанию возраст скрыт</small></span><input type="checkbox" checked={editAgePublic} onChange={e=>changeAgeVisibility(e.target.checked)}/></label><div className="settings-row static-row">Статус активности <small>Показываем «в сети» или время последнего посещения</small></div><details className="legal-details"><summary>Политика конфиденциальности</summary><p>DTR хранит данные аккаунта, профиль, сообщения и вложения, необходимые для работы мессенджера. Заметки доступны только владельцу аккаунта. Обращения поддержки доступны автору и уполномоченным сотрудникам поддержки. Не отправляй в чат пароли, платёжные данные и другую особо чувствительную информацию.</p><p>Это краткое описание текущей работы приложения, а не юридическое заключение. Перед публичным запуском владелец сервиса должен дополнить документ контактами, сроками хранения и порядком удаления данных.</p></details><details className="legal-details"><summary>Пользовательское соглашение</summary><p>Используя DTR, пользователь обязуется не нарушать закон, не выдавать себя за других людей, не рассылать спам и не пытаться получить доступ к чужим аккаунтам или перепискам. Команда DTR может ограничивать доступ при злоупотреблениях.</p><p>Текст является базовым проектом правил и требует проверки и дополнения владельцем сервиса перед тем, как считать его официальным соглашением.</p></details></section>
<section className="settings-card"><h3>Данные и хранение</h3><button className="settings-row" onClick={()=>{setPage("notes");setActive(null);loadNotes();}}>Мои заметки <span>›</span></button><button className="settings-row" onClick={()=>{setPage("support");setActive(null);setSelectedTicket(null);loadTickets();}}>Поддержка и предложения <span>›</span></button></section>
<section className="settings-card"><h3>Аккаунт</h3><div className="settings-row static-row">Версия приложения <b>0.6.0</b></div><button className="danger-action" onClick={logout}>Выйти из аккаунта</button></section></div></>
:page==="notes"?<><header className="conversation-head"><button className="back-btn" onClick={()=>setPage("chat")}>←</button><div><b>Мои заметки</b><small>Личное пространство — видно только тебе</small></div></header><div className="messages settings-content"><section className="settings-card"><h3>Новая заметка</h3><input className="search" value={noteTitle} onChange={e=>setNoteTitle(e.target.value)} placeholder="Название заметки"/><textarea className="note-editor" value={noteBody} onChange={e=>setNoteBody(e.target.value)} maxLength={5000} placeholder="Запиши важную мысль…"/><button className="primary-action" onClick={saveNote} disabled={!noteTitle.trim()&&!noteBody.trim()}>Сохранить заметку</button></section>{notes.map(n=><article className="settings-card note-card" key={n.id}><div className="note-card-head"><h3>{n.title||"Без названия"}</h3><button className="danger-small" onClick={()=>deleteNote(n.id)}>Удалить</button></div><p>{n.body}</p><small>{new Date(n.updated_at).toLocaleString("ru-RU")}</small></article>)}</div></>
:page==="support"?<><header className="conversation-head"><button className="back-btn" onClick={()=>{setPage("chat");setSelectedTicket(null)}}>←</button><div><b>{["owner","admin","helper","my_love"].includes(me.role||"")?"Центр поддержки DTR":"Поддержка DTR"}</b><small>{["owner","admin","helper","my_love"].includes(me.role||"")?"Обращения пользователей":"Вопросы, проблемы и предложения"}</small></div></header><div className="messages settings-content"><section className="settings-card"><h3>Создать обращение</h3><input className="search" value={supportSubject} onChange={e=>setSupportSubject(e.target.value)} placeholder="Тема обращения"/><select className="support-select" value={supportCategory} onChange={e=>setSupportCategory(e.target.value)}><option value="question">Вопрос</option><option value="problem">Проблема</option><option value="suggestion">Предложение</option></select><textarea className="note-editor" value={supportBody} onChange={e=>setSupportBody(e.target.value)} maxLength={4000} placeholder="Опиши подробно, чем можем помочь…"/><button className="primary-action" onClick={createTicket} disabled={!supportSubject.trim()||!supportBody.trim()}>Отправить в поддержку</button></section><section className="settings-card"><h3>{["owner","admin","helper","my_love"].includes(me.role||"")?"Все обращения команды":"Мои обращения"}</h3>{tickets.map(t=><button className="ticket-row" key={t.id} onClick={()=>openTicket(t)}><span><b>{t.subject}</b><small>{t.display_name||"Вы"} · {t.category==="suggestion"?"Предложение":t.category==="problem"?"Проблема":"Вопрос"} · {t.status==="closed"?"Закрыто":t.status==="in_progress"?"В работе":"Открыто"}</small><small>{t.last_message||""}</small></span><b>›</b></button>)}{tickets.length===0&&<p className="settings-hint">Пока обращений нет.</p>}</section>{selectedTicket&&<section className="settings-card"><h3>{selectedTicket.subject}</h3><small>{selectedTicket.display_name||"Обращение"} · {selectedTicket.status}</small><div className="support-thread">{supportMessages.map(m=><div key={m.id} className={m.senderId===me.id?"support-message mine":"support-message"}><b>{m.display_name||m.username||"Участник"}</b><p>{m.body}</p><small>{new Date(m.created_at).toLocaleString("ru-RU")}</small></div>)}</div>{["owner","admin","helper","my_love"].includes(me.role||"")&&<div className="theme-choice"><button className="theme-option" onClick={()=>updateTicketStatus("in_progress")}>В работу</button><button className="theme-option" onClick={()=>updateTicketStatus("closed")}>Закрыть</button><button className="theme-option" onClick={()=>updateTicketStatus("open")}>Открыть</button></div>}<textarea className="note-editor" value={supportDraft} onChange={e=>setSupportDraft(e.target.value)} placeholder="Ответить…"/><button className="primary-action" onClick={sendSupportReply} disabled={!supportDraft.trim()}>Отправить ответ</button></section>}</div></>
:page==="admin"?<><header className="conversation-head"><button className="back-btn" onClick={()=>setPage("chat")}>←</button><div><b>Панель управления DTR</b><small>Управление ролями пользователей</small></div></header><div className="messages settings-content"><section className="settings-card"><h3>Найти пользователя</h3><input className="search" value={adminSearch} onChange={e=>setAdminSearch(e.target.value)} placeholder="Введите логин…"/>{adminResults.map(u=><div className="admin-user-row" key={u.id}><Avatar user={u}/><span><b>{u.displayName}</b><small>@{u.username} · {roleLabel(u.role)}</small></span><select value={u.role||"member"} onChange={e=>assignRole(u,e.target.value)}><option value="member">Участник DTR</option><option value="vip">VIP</option><option value="helper">Хелпер</option>{me.role==="owner"&&<><option value="admin">Администратор</option><option value="my_love">Моя любовь</option></>}</select></div>)}</section><section className="settings-card"><h3>Права ролей</h3><p className="settings-hint">Владелец управляет всеми ролями. Администратор может назначать участника, VIP и хелпера. Хелпер и «Моя любовь» получают обращения поддержки. Назначение владельца закрыто от панели.</p></section></div></>
:active?<><header className="conversation-head"><button className="back-btn mobile-back" onClick={()=>{setActive(null);setMessages([])}}>←</button><button className="chat-header-profile" onClick={()=>active.type==="group"?setGroupInfoOpen(true):viewProfile(active.user)}><Avatar user={active.type==="group"?null:active.user} label={active.type==="group"?(active.title||"Г").slice(0,1):undefined}/><span><b>{activeTitle}</b><small>{activeSubtitle}</small></span></button>{active.type==="direct"&&<><button className="icon-btn call-action" onClick={()=>startCall(false)} title="Голосовой звонок" disabled={Boolean(call)}>☎</button><button className="icon-btn call-action" onClick={()=>startCall(true)} title="Видеозвонок" disabled={Boolean(call)}>▣</button></>}<button className="icon-btn header-more" onClick={()=>active.type==="group"?setGroupInfoOpen(true):viewProfile(active.user)} title={active.type==="group"?"Участники":"Профиль"}>•••</button></header><div className="messages">{messages.map(m=><div key={m.id} className={m.senderId===me.id?"bubble mine":"bubble"}>{active.type==="group"&&m.senderId!==me.id&&<small className="sender-name">{m.displayName||m.username||"Участник"}</small>}{(m.messageType==="image"||m.messageType==="audio")&&m.mediaUrl?<MessageMedia url={m.mediaUrl} type={m.messageType} token={token||""}/>:null}{m.body&&m.body!=="Фото"&&m.body!=="Голосовое сообщение"&&<p>{m.body}</p>}{(m.messageType==="audio"||m.messageType==="image")&&(!m.body||m.body==="Фото"||m.body==="Голосовое сообщение")&&<small className="media-label">{m.messageType==="audio"?"Голосовое сообщение":"Фото"}</small>}<time>{new Date(m.createdAt).toLocaleTimeString("ru-RU",{hour:"2-digit",minute:"2-digit"})}</time></div>)}</div><form className="composer" onSubmit={send}><div className="composer-tools"><input ref={photoInput} className="hidden-file" type="file" accept="image/png,image/jpeg,image/webp,image/gif" onChange={e=>sendMedia(e.target.files?.[0])}/><button type="button" className="tool-btn" title="Отправить фото" onClick={()=>photoInput.current?.click()} disabled={uploadingMedia||recording}>＋</button><button type="button" className={emojiOpen?"tool-btn emoji-active":"tool-btn"} title="Эмодзи" onClick={()=>setEmojiOpen(v=>!v)} disabled={recording||uploadingMedia}>☺</button><button type="button" className={recording?"tool-btn recording":"tool-btn"} title={recording?"Остановить запись":"Записать голосовое сообщение"} onClick={recording?stopRecording:startRecording} disabled={uploadingMedia}>{recording?"■":"🎙"}</button></div>{emojiOpen&&<div className="emoji-picker">{emojiList.map(emoji=><button type="button" key={emoji} onClick={()=>{setDraft(old=>old+emoji);setEmojiOpen(false)}}>{emoji}</button>)}</div>}<input value={draft} onChange={e=>setDraft(e.target.value)} placeholder={recording?"Идёт запись голосового…":uploadingMedia?"Отправка файла…":"Написать сообщение…"} maxLength={4000} disabled={recording||uploadingMedia}/><button className="send-btn" aria-label="Отправить сообщение" title="Отправить сообщение" disabled={!draft.trim()||recording||uploadingMedia}>{uploadingMedia?<span className="send-spinner">…</span>:"➤"}</button></form></>:<div className="empty"><div className="brand-mark">д</div><h2>Добро пожаловать в дтр</h2><p>Найди человека по логину или создай группу.</p><button className="primary-action empty-action" onClick={()=>setGroupOpen(true)}>＋ Создать группу</button></div>}
      {error&&<button className="toast" onClick={()=>setError("")}>{error} ×</button>}
    </section>

    {profileTarget&&<div className="modal-backdrop" onClick={()=>setProfileTarget(null)}><section className="profile-modal" onClick={e=>e.stopPropagation()}><header className="modal-head"><button className="back-btn" onClick={()=>setProfileTarget(null)}>←</button><b>Профиль</b><button className="icon-btn" onClick={()=>setProfileTarget(null)}>×</button></header><div className="profile-hero"><Avatar user={profileTarget}/><h2>{profileTarget.displayName}</h2><p>@{profileTarget.username}</p></div><div className="profile-details"><div><small>О СЕБЕ</small><p>{profileTarget.bio||"Пока ничего не рассказал о себе."}</p></div>{profileTarget.age!==null&&<div><small>ВОЗРАСТ</small><p>{profileTarget.age}</p></div>}<div><small>РОЛЬ</small><p>{roleLabel(profileTarget.role)}</p></div><div><small>АКТИВНОСТЬ</small><p>{presenceText(profileTarget)}</p></div></div>{profileTarget.id===me.id&&<button className="primary-action" onClick={()=>{setProfileTarget(null);openEditProfile()}}>Редактировать профиль</button>}</section></div>}
    {editOpen&&<div className="modal-backdrop" onClick={()=>setEditOpen(false)}><section className="edit-modal" onClick={e=>e.stopPropagation()}><header className="modal-head"><button className="back-btn" onClick={()=>setEditOpen(false)}>←</button><b>Изменить профиль</b><button className="icon-btn" onClick={()=>setEditOpen(false)}>×</button></header><div className="edit-avatar"><Avatar user={me}/><label className="upload-avatar-btn">Изменить фото<input type="file" accept="image/png,image/jpeg,image/webp,image/gif" onChange={e=>uploadAvatar(e.target.files?.[0])}/></label></div><label className="field-label">Имя<input value={editName} onChange={e=>setEditName(e.target.value)} maxLength={40}/></label><label className="field-label">О себе<textarea value={editBio} onChange={e=>setEditBio(e.target.value)} maxLength={160} placeholder="Расскажи немного о себе…"/></label><label className="field-label">Возраст <small>необязательно</small><input type="number" min="13" max="99" value={editAge} onChange={e=>setEditAge(e.target.value)} placeholder="Например, 16"/></label><label className="setting-toggle age-privacy"><span><b>Показывать возраст</b><small>Возраст скрыт, пока ты сам не включишь эту настройку</small></span><input type="checkbox" checked={editAgePublic} onChange={e=>setEditAgePublic(e.target.checked)}/></label><button className="primary-action save-profile-btn" onClick={saveProfile} disabled={busy}>Сохранить изменения</button></section></div>}
    {groupOpen&&<div className="modal-backdrop" onClick={()=>setGroupOpen(false)}><section className="group-modal" onClick={e=>e.stopPropagation()}><header className="modal-head"><button className="back-btn" onClick={()=>setGroupOpen(false)}>←</button><b>Новая группа</b><button className="icon-btn" onClick={()=>setGroupOpen(false)}>×</button></header><label className="field-label">Название группы<input value={groupTitle} onChange={e=>setGroupTitle(e.target.value)} maxLength={60} placeholder="Например, Друзья"/></label><label className="field-label">Добавить участников<input value={groupSearch} onChange={e=>setGroupSearch(e.target.value)} placeholder="Поиск по логину…"/></label>{groupResults.map(u=><button className="person modal-person" key={u.id} onClick={()=>setSelectedUsers(old=>[...old,u])}><Avatar user={u}/><span><b>{u.displayName}</b><small>@{u.username}</small></span><span className="add-mark">＋</span></button>)}<div className="selected-members">{selectedUsers.map(u=><button key={u.id} onClick={()=>setSelectedUsers(old=>old.filter(x=>x.id!==u.id))}>{u.displayName} ×</button>)}</div><button className="primary-action save-profile-btn" onClick={createGroup} disabled={busy||!groupTitle.trim()||selectedUsers.length===0}>{busy?"Создаём…":"Создать группу"}</button><small className="settings-hint">До 20 участников в одной группе.</small></section></div>}
    {groupInfoOpen&&active?.type==="group"&&<div className="modal-backdrop" onClick={()=>setGroupInfoOpen(false)}><section className="group-modal" onClick={e=>e.stopPropagation()}><header className="modal-head"><button className="back-btn" onClick={()=>setGroupInfoOpen(false)}>←</button><b>Участники группы</b><button className="icon-btn" onClick={()=>setGroupInfoOpen(false)}>×</button></header><div className="group-info-title"><Avatar user={null} label={(active.title||"Г").slice(0,1)}/><h3>{active.title}</h3><small>{active.members.length} участников</small></div>{active.members.map(u=><button className="person modal-person" key={u.id} onClick={()=>{setGroupInfoOpen(false);viewProfile(u)}}><Avatar user={u}/><span><b>{u.displayName}</b><small>@{u.username}{u.id===me.id?" · Вы":""}</small></span></button>)}<label className="field-label">Добавить участника<input value={groupAddSearch} onChange={e=>setGroupAddSearch(e.target.value)} placeholder="Поиск по логину…"/></label>{groupAddResults.map(u=><button className="person modal-person" key={u.id} onClick={()=>addGroupMember(u)}><Avatar user={u}/><span><b>{u.displayName}</b><small>@{u.username}</small></span><span className="add-mark">＋</span></button>)}</section></div>}
    {call&&<div className="call-backdrop"><section className="call-window"><header className="call-top"><span>{call.video?"Видеозвонок":"Голосовой звонок"}</span><span>{call.status==="incoming"?"Входящий":call.status==="calling"?"Вызов…":call.status==="active"?"На связи":"Соединение…"}</span></header><div className="call-peer"><span className="call-avatar">{call.peerAvatar?<img src={call.peerAvatar} alt="" />:call.peerName.slice(0,1).toUpperCase()}</span><h2>{call.peerName}</h2><p>{call.status==="incoming"?"Пытается связаться с вами":call.status==="active"?"Звонок активен":"Ожидаем подключения"}</p></div>{call.video&&!(remoteStream?.getVideoTracks().some(t=>t.readyState==="live"&&t.enabled))&&<div className="call-video-placeholder">{call.peerAvatar?<img src={call.peerAvatar} alt="Фото собеседника"/>:<span>{call.peerName.slice(0,1).toUpperCase()}</span>}<small>Камера собеседника пока недоступна</small></div>}<video ref={remoteVideoRef} className={call.video&&remoteStream?.getVideoTracks().some(t=>t.readyState==="live"&&t.enabled)?"remote-video":"remote-video audio-only"} autoPlay playsInline/><audio ref={remoteAudioRef} className="remote-audio" autoPlay/><video ref={localVideoRef} className={call.video?"local-video mirrored-local-video":"local-video hidden-video"} autoPlay muted playsInline/><div className="call-controls">{call.status==="incoming"?<><button className="call-accept" onClick={acceptCall}>Принять</button><button className="call-end" onClick={()=>finishCall()}>Отклонить</button></>:<><button className={micMuted?"call-control toggled":"call-control"} onClick={()=>{const next=!micMuted;localStreamRef.current?.getAudioTracks().forEach(t=>t.enabled=!next);setMicMuted(next)}}>🎙</button>{call.video&&<button className={cameraOff?"call-control toggled":"call-control"} onClick={()=>{const next=!cameraOff;localStreamRef.current?.getVideoTracks().forEach(t=>t.enabled=!next);setCameraOff(next)}}>▣</button>}<button className={speakerOn?"call-control toggled":"call-control"} onClick={toggleSpeaker} title="Громкая связь">🔊</button><button className="call-end" onClick={()=>finishCall()}>Завершить</button></>}</div></section></div>}
  </main>;
}

function roleLabel(role?:string){const labels:Record<string,string>={owner:"Владелец",admin:"Администратор",helper:"Хелпер",vip:"VIP",my_love:"Моя любовь",member:"Участник DTR"};return labels[role||"member"]||"Участник DTR";}
function presenceText(user:User|null|undefined){if(!user)return "Не в сети";if(user.online)return "В сети";if(!user.lastSeenAt)return "Был(а) недавно";return "Был(а) в сети "+new Date(user.lastSeenAt).toLocaleString("ru-RU",{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"});}
function Avatar({user,label}:{user:User|null;label?:string}){const [failed,setFailed]=useState(false);useEffect(()=>setFailed(false),[user?.avatarUrl]);return <span className={"avatar-wrap"+(user?.online?" is-online":"")}><span className="avatar">{user?.avatarUrl&&!failed?<img src={user.avatarUrl} alt="" onError={()=>setFailed(true)}/>:((label||user?.displayName?.slice(0,1)||"D").slice(0,1).toUpperCase())}</span>{user?.statusEmoji&&<i className="avatar-status">{user.statusEmoji}</i>}</span>}

function MessageMedia({url,type,token}:{url:string;type:"image"|"audio"|undefined;token:string}){
  const [src,setSrc]=useState("");
  useEffect(()=>{let active=true;let objectUrl="";fetch(url,{headers:{Authorization:"Bearer "+token}}).then(response=>{if(!response.ok)throw new Error("media");return response.blob()}).then(blob=>{objectUrl=URL.createObjectURL(blob);if(active)setSrc(objectUrl)}).catch(()=>{});return()=>{active=false;if(objectUrl)URL.revokeObjectURL(objectUrl)};},[url,token]);
  if(!src)return <small className="media-label">Загрузка вложения…</small>;
  return type==="image"?<img className="message-image" src={src} alt="Фото в сообщении"/>:<audio className="message-audio" controls src={src}/>;
}